import { Component, EventEmitter, Input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { CreditoDespacho } from '../../../models/credito.despacho';
import { CreditoDespachoService } from '../../../controllers/credito.despacho.service';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';
import { filter, firstValueFrom } from 'rxjs';
import { UtilsService } from '../../../services/utils.service';

const FORM_DEF:Form=[
  {
    key:'despacho_id',
    label:'Despacho',
    apiUrl:'api/despachos',
    keyList:'id',
    keyDetalle:'nombre',
    style:{
      div:'col-12 col-sm-6 p-3'
    }
  },
  {
    key:'fecha_inicio',
    label:'Fecha Inicio',
    type:'date',
    validator:{
      required: true
    },
    style:{
      div:'col-12 col-sm-6 p-3'
    },    
  },
]

@Component({
    selector: 'app-form-juridico-despacho',
    imports: [
        GenericFormComponent,
    ],
    templateUrl: './form-juridico-despacho.component.html',
    styleUrl: './form-juridico-despacho.component.css'
})
export class FormJuridicoDespachoComponent {
  @ViewChild('genericForm') genericForm ?: GenericFormComponent<CreditoDespacho>
  @Input() credito?:Credito
  @Input() edit?:CreditoDespacho
  @Output() editChange = new EventEmitter<CreditoDespacho>()
  @Input() localForm=false
  form=FORM_DEF

  constructor(
    public creditoDespachoController:CreditoDespachoService,
    private dialogService: VanillaDialogService,
    private utils: UtilsService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(this.credito && changes['credito'] && this.credito.creditos_despachos){
      this.edit = this.utils.despachoActualFromCredito(this.credito, new Date())
    }
  }

  public async delete(){
    if(this.edit?.id){
      const resp = await firstValueFrom(this.dialogService.show({
        title: 'Confirmar eliminación',
        body: '¿Está seguro de que desea eliminar este despacho?',
        respYes: 'Sí, eliminar',
        respNo: 'No, cancelar'
      }).pipe(filter(v => v!=null)))

      if(resp.closedByAgree){
        const success = await this.creditoDespachoController.switch(this.edit)
        if(success){          
          this.edit = undefined
          this.genericForm?.cleanForm()
        }
      }
    }
  }
}
