import { Pipe, PipeTransform } from '@angular/core';
import { Credito } from '../models/credito.model';

@Pipe({
  name: 'resultadoUltimaGestion',
  standalone: true
})
export class ResultadoUltimaGestionPipe implements PipeTransform {

  transform(credito: Credito |undefined, ...args: unknown[]): unknown {
    if(!credito || !credito.credito_evento_cobros?.length) return null;
    const ultimaGestion = credito.credito_evento_cobros
      .sort((a, b) => new Date(b.fecha??'').getTime() - new Date(a.fecha??'').getTime())
      [0];
    return ultimaGestion.otro_resultado ?? ultimaGestion.resultado;
  }

}
