import { Component } from '@angular/core';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';

import { Juridico } from '../../../models/juridico.model';
import { FormJuridicoComponent } from "../form-juridico/form-juridico.component";
import { ViewRelacionConveniosComponent } from "../../estado-cuenta/shared/view-relacion-convenios/view-relacion-convenios.component";
import { ViewGestionesCobroComponent } from "../../estado-cuenta/shared/view-gestiones-cobro/view-gestiones-cobro.component";
import { FormJuridicoDespachoComponent } from "../form-juridico-despacho/form-juridico-despacho.component";
import { JuridicoEventosJuzgadoComponent } from "../juridico-eventos-juzgado/juridico-eventos-juzgado.component";
import { BitacoraCobranzaComponent } from "../bitacora-cobranza/bitacora-cobranza.component";
import { JuridicoBienesInmueblesComponent } from "../juridico-bienes-inmuebles/juridico-bienes-inmuebles.component";
import { JuridicoComentariosComponent } from "../juridico-comentarios/juridico-comentarios.component";
import { DatoPersonaFisica } from '../../../models/dato.persona.fisica.model';
import { DatoPersonaMoral } from '../../../models/dato.persona.moral.model';
import { TelefonosPipe } from '../../../pipes/telefonos.pipe';
import { CollapsableComponent } from "../../../shared/collapsable/collapsable.component";
import { FormEtapaJuridicoComponent } from "../form-juridico/form-etapa-juridico/form-etapa-juridico.component";
import { CobroModalidad, CreditoEventoCobro } from '../../../models/credito.evento.cobro';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { EjecucionCobroComponent } from "../../cobranza/ejecucion-cobro/ejecucion-cobro.component";
import { FechaEtapaProcesalPipe } from '../../../pipes/fecha-etapa-procesal.pipe';
import { ResultadoUltimaGestionPipe } from '../../../pipes/resultado-ultima-gestion.pipe';
import { FechaUltimaGestionPipe } from '../../../pipes/fecha-ultima-gestion.pipe';
import { ResumenEtapasComponent } from "../resumen-etapas/resumen-etapas.component";
import { EstadoProcesalPipe } from '../../../pipes/estado-procesal.pipe';


@Component({
    selector: 'app-resumen-juridico',
    imports: [
    FormJuridicoComponent,
    ViewRelacionConveniosComponent,
    ViewGestionesCobroComponent,
    FormJuridicoDespachoComponent,
    JuridicoEventosJuzgadoComponent,
    BitacoraCobranzaComponent,
    JuridicoBienesInmueblesComponent,
    JuridicoComentariosComponent,
    TelefonosPipe,
    CollapsableComponent,    
    FormEtapaJuridicoComponent,
    EjecucionCobroComponent,
    FechaEtapaProcesalPipe,
    ResultadoUltimaGestionPipe,
    FechaUltimaGestionPipe,
    EstadoProcesalPipe,
    ResumenEtapasComponent
],
    templateUrl: './resumen-juridico.component.html',
    styleUrl: './resumen-juridico.component.css'
})
export class ResumenJuridicoComponent {
  credito?: Credito
  personaFisica?: DatoPersonaFisica | null
  personaMoral?: DatoPersonaMoral | null
  juridico?: Juridico
  tabs: string[] = ['Cliente', 'Etapa', 'Juridico', 'Cobros', 'Bienes Inmuebles', 'Comentarios', 'Despacho']
  tabSelected = 'Cliente'
  cobroEdit?: CreditoEventoCobro

  constructor(
    private creditoController: CreditoService,
    private route: ActivatedRoute,
    private localStorage: LocalStorageService,
    public utils: UtilsService,
  ) { }

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      const id = params['credito_id']
      if (id) {
        this.setData(id)
      }
    })
  }

  public async setData(id: number | undefined) {
    if (!id) return;
    this.credito = await this.creditoController.find(id, ['*'])
    this.juridico = this.credito?.juridicos
    this.personaFisica = this.credito?.datos_persona_fisica
    this.personaMoral = this.credito?.datos_personas_morales
    console.log(this.credito)
  }

  selectTab(tab: string) {
    if (tab === 'Cliente') {
      this.setData(this.credito?.id)
    }
    this.tabSelected = tab
  }

  public isAlertShown(): string {
    if (!this.juridico || !this.juridico.juridicos_etapas_judiciales?.length) return '';
    this.juridico.juridicos_etapas_judiciales.sort((a, b) => new Date(a.updated_at!).getTime() - new Date(b.updated_at!).getTime())
    const ultimaEtapaActiva = this.juridico.juridicos_etapas_judiciales[this.juridico.juridicos_etapas_judiciales.length - 1];
    if (ultimaEtapaActiva.fecha) {
      const fechaEtapa = new Date(ultimaEtapaActiva.fecha.substring(0, 10) + 'T17:00:00Z');
      const hoy = new Date();

      // Calculate difference in milliseconds and convert to days
      const diffTime = hoy.getTime() - fechaEtapa.getTime();
      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

      if (diffDays >= 60) {
        return `¡Alerta! Lleva más ${diffDays} días desde la última actualización de la etapa.`;
      }
    }
    if (!ultimaEtapaActiva.fecha) {
      return '¡Alerta! La última etapa asiganda no tiene fecha'
    }
    return '';
  }


  /**
   * Inicia el proceso de creación de una nueva cobranza para el crédito actual.
   *
   * Este método crea un nuevo evento de cobro asociado al crédito seleccionado,
   * utilizando la modalidad de cobro especificada. El evento de cobro se asigna
   * al usuario actual obtenido del almacenamiento local.
   *
   * @param modalidad - La modalidad de cobro a utilizar (por ejemplo, 'efectivo', 'transferencia', etc.).
   * @returns Una promesa que se resuelve cuando el evento de cobro ha sido creado y asignado.
   */
  public async nuevaCobranza(modalidad: CobroModalidad): Promise<void> {
    const usuario = this.localStorage.getUser();
    if (this.cobroEdit && this.cobroEdit.modalidad == modalidad) {
      this.cobroEdit = undefined
      return;
    }
    this.cobroEdit = {
      id: 0,
      credito_id: this.credito?.id ?? 0,
      modalidad: modalidad,
      usuario_ejecutivo_id: usuario.id,
      resultado: 'NO REALIZADO',
      usuario_id: usuario.id,
      fecha: new Date().toISOString().substring(0, 10),
      comentario: '',
      deleted_at: '',
      created_at: '',
      updated_at: '',
    }
  }

  /**
  * Inserta a la lista local de cobros el evento recien guardado y lo vuelve undefined para ocultar el formulario
  */
  public onCobroSaved() {
    this.credito?.credito_evento_cobros?.unshift(this.utils.copyOf(this.cobroEdit))
    this.cobroEdit = undefined
  }
}
