import { Component } from '@angular/core';
import { Button, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { CreditoService } from '../../../controllers/credito.service';
import { CREDITOS_ADVANCED_SEARCH } from '../../creditos/creditos.busqueda.avanzada';
import { EstadoCuenta } from '../../../models/estado.cuenta';
import { Router } from '@angular/router';
import { Credito } from '../../../models/credito.model';
import { CREDITOS_FILTERS } from '../../creditos/creditos.simple.filters';
import { FormsModule } from '@angular/forms';
import { UtilsService } from '../../../services/utils.service';

const TABLA_DEF:TableDefinition={
  emptyMsg:'No hay creditos con estados de cuenta activos.',
  columns:[
    {
      key:'id',
      header:'ID',
    },
    {
      key:'row',
      header:'Estado',
      function:(credito:Credito)=>{
        return credito.estado_cuenta?.credito_status??'CARTERA'
      }
    },
    {
      key:'row',
      header:'Nombre Cliente',
      function:(row:Credito,utils:UtilsService)=>{
        return utils.nombreClienteFromCredito(row)
      }
    },
    {
      key:'row',
      header:'Nombre Comercial',
      function:(row:Credito,utils:UtilsService)=>{
        return utils.nombreNegocioFromCredito(row)
      }
    },
    {
      key:'estados_cuenta',
      header:'Liquidar Sin Moratorios',
      function:(estado:EstadoCuenta) => {
        if(typeof estado.estado_cuenta =='string'){
          return JSON.parse(estado.estado_cuenta).estadistica['LIQUIDAR SIN MORATORIOS'].toString()
        }
        return estado.estado_cuenta.estadistica['LIQUIDAR SIN MORATORIOS'].toString()
      },
      pipe:'currency'
    },
    {
      key:'estados_cuenta',
      header:'Pagos Vencidos',
      function:(estado:EstadoCuenta) => {
        return (estado.pagos_requeridos-estado.pagos_realizados).toString()
      },
    },
    {
      key:'estados_cuenta',
      header:'Vencido desde',
      subKey:'vencido_desde',
      pipe:'date'
    },
    {
      key:'productos_financieros',
      subKey:'alias',
      header:'P Financiero'
    },
    {
      key:'sucursales',
      subKey:'nombre',
      header:'Último Estado Procesal'
    },
    {
      key:'created_at',
      header:'Fecha Último Estado Procesal',
      pipe:'date'
    },
  ]
}
const EDITAR_BUTTON:Button={
  style:{
    button:'btn btn-sm btn-info',
    icon:'bi bi-eye-fill'
  },
}

const ASIGNAR_JURIDICO: RowButton={
  key:'juridico',
  text:'Pasar a Juridico',
  style:{
    button:'btn btn-sm btn-primary',
    icon:'bi bi-journal-plus'
  }
}

const BARRA_BUTONES:HeaderButton[]=[
  {
    key:'no-juridico',
    text:'CARTERA',
    style:{
      button:'btn btn-secondary scale-05 shadow'
    }
  },
  {
    key:'no-juridico',
    text:'CARTERA EXTRAJUDICIAL',
    style:{
      button:'btn btn-secondary scale-05 shadow'
    }
  },
  {
    key:'no-juridico',
    text:'CARTERA JUDICIAL',
    style:{
      button:'btn btn-secondary scale-05 shadow'
    }
  },
  {
    key:'ver-todos',
    text:'TODOS',
    style:{
      button:'btn btn-secondary scale-05 shadow'
    }
  }
]

@Component({
    selector: 'app-atrasados-creditos',
    imports: [
        TablaComponent,
        FormsModule,
    ],
    templateUrl: './atrasados-creditos.component.html',
    styleUrl: './atrasados-creditos.component.css'
})
export class AtrasadosCreditosComponent {
  tabla = TABLA_DEF
  edit=EDITAR_BUTTON
  advancedSearch= CREDITOS_ADVANCED_SEARCH
  simpleFilters= CREDITOS_FILTERS
  asignarJuridico= ASIGNAR_JURIDICO
  barraButtons= BARRA_BUTONES
  filtros:{
    filtro:string;
    meses_vencidos:number|null;
    incluir_juridico:number|null;
    monto_atrasado:number|null;
    adeudo_total:number|null;
  }={
    filtro: 'estado',
    meses_vencidos: null,
    incluir_juridico: null,
    monto_atrasado: null,
    adeudo_total: null
  }
  constructor(
    public creditoController:CreditoService,
    private router:Router,
  ){}

  onRowButtonClick(event:RowButtonClickEvent<Credito>){
    if(event.row.juridicos){
      this.router.navigate(['/main/juridico/'+event.row.id+'/'+event.row.juridicos.id])
      return
    }
    this.router.navigate(['/main/juridico/'+event.row.id+'/asignar'])
  }

  onHeaderButtonClick(key:string){
    switch(key){
      case 'no-juridico':
        this.filtros={
          ...this.filtros,
          incluir_juridico:-1
        }
        break;
      case 'ver-todos':
        this.filtros={
          ...this.filtros,
          incluir_juridico:1
        }
    }
  }

  limpiarFiltros(){
    this.filtros.meses_vencidos=null
    this.filtros.incluir_juridico=null
    this.filtros.monto_atrasado=null
    this.filtros.adeudo_total=null
  }
}
