import { DatePipe } from '@angular/common';
import { Component, Input } from '@angular/core';
import { JuridicoComentario } from '../../../models/juridico.comentario';
import { Credito } from '../../../models/credito.model';
import { JuridicoComentarioService } from '../../../controllers/juridico.comentario.service';
import { FormsModule } from '@angular/forms';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

@Component({
    selector: 'app-juridico-comentarios',
    imports: [
    DatePipe,
    FormsModule
],
    templateUrl: './juridico-comentarios.component.html',
    styleUrl: './juridico-comentarios.component.css'
})
export class JuridicoComentariosComponent {
  @Input() credito?:Credito
  comentarios:JuridicoComentario[]=[]

  comentarioForm:string=''

  constructor(
    private comentarioController:JuridicoComentarioService,
    private localStorage: LocalStorageService,
  ){}

  ngOnInit(){
    this.setComentarios()
  }

  private async setComentarios(){
    this.comentarios= await this.comentarioController.all({
      juridico_id:this.credito?.juridicos!.id,
      deleted_at:null,
    }, ['usuario']);
  }

  public async nuevoComentario(){
    if(!this.comentarioForm) return;
    const res = await this.comentarioController.new({
      juridico_id:this.credito?.juridicos?.id,
      comentario:this.comentarioForm
    })
    if(res){
      const usuario= this.localStorage.getUser()
      res.usuario=usuario
      this.comentarios.push(res)
      this.comentarioForm=''
    }
  }
}
