import { Component, Input, SimpleChanges } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { JuridicoJuzgadoEvento } from '../../../models/juridico.juzgado.evento';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { JuridicoJuzgadoEventoService } from '../../../controllers/juridico.juzgado.evento.service';
import { UtilsService } from '../../../services/utils.service';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';
import { filter, firstValueFrom } from 'rxjs';

@Component({
    selector: 'app-juridico-eventos-juzgado',
    imports: [
    DatePipe,
    FormsModule
],
    templateUrl: './juridico-eventos-juzgado.component.html',
    styleUrl: './juridico-eventos-juzgado.component.css'
})
export class JuridicoEventosJuzgadoComponent {
  @Input() credito?:Credito
  eventoForm:JuridicoJuzgadoEvento={
    juridico_id: 0,
    descripcion: '',
    fecha: '',
    usuario_id: 0,
    id: 0,
    deleted_at: null,
    created_at: '',
    updated_at: null
  }

  showForm=false

  constructor(
    private eventoController: JuridicoJuzgadoEventoService,
    private utils:UtilsService,
    private dialogService: VanillaDialogService
  ){
  }

  ngOnChanges( changes:SimpleChanges){
    if(changes['credito'] && this.credito && this.credito.juridicos){
      this.eventoForm.juridico_id= this.credito.juridicos.id
    }
  }

  public async nuevoEvento(){
    const resp = await firstValueFrom(this.dialogService.show({
      title: 'Guardar nuevo evento',
      body: '¿Está seguro de que desea guardar este nuevo evento?',
      respYes: 'Sí, guardar',
      respNo: 'No, cancelar'
    }).pipe(filter(v => v!=null)))

    if(resp.closedByAgree){
      if(!this.credito?.juridicos){
        this.dialogService.show({
          title: 'Error',
          body: 'Para agregar eventos de juzgados, el crédito debe estar primero en estado jurídico. Actualice el estado del crédito a jurídico para habilitar esta funcionalidad.',
          respYes: 'Aceptar'
        })
        return;
      }
      if(!this.credito.juridicos.juridicos_juzgados_eventos){
        this.credito.juridicos.juridicos_juzgados_eventos = [];
      }
      const res= await this.eventoController.new(this.eventoForm)
      if(!res) {
        this.dialogService.show({
          title: 'Error',
          body: 'No se pudo crear el evento.',
          respYes: 'Aceptar'
        })
        return;
      }
      this.credito.juridicos.juridicos_juzgados_eventos.push(res)
      this.eventoForm={
        juridico_id: this.credito!.juridicos!.id,
        descripcion: '',
        fecha: new Date().toISOString().substring(0,10),
        usuario_id: 0,
        id: 0,
        deleted_at: null,
        created_at: '',
        updated_at: null
      }
      this.showForm=false
    }
  }

  async delete(row:JuridicoJuzgadoEvento){
    const res= await this.eventoController.switch(row,{},false)
    if(res){
      this.utils.localDelete(this.credito?.juridicos?.juridicos_juzgados_eventos,row)
    }
  }
}
