import { Component, Input } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { JuridicoBienInmuebleService } from '../../../controllers/juridico.bien.inmueble.service';
import { JuridicoBienInmueble } from '../../../models/juridico.bien.inmueble';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
    selector: 'app-juridico-bienes-inmuebles',
    imports: [
    DatePipe,
    FormsModule
],
    templateUrl: './juridico-bienes-inmuebles.component.html',
    styleUrl: './juridico-bienes-inmuebles.component.css'
})
export class JuridicoBienesInmueblesComponent {
  @Input() credito?:Credito  
  showForm=false
  bienInmueble:string=''

  bienesInmuebles:JuridicoBienInmueble[]=[]

  constructor(
    private juridicoBienesController:JuridicoBienInmuebleService,
  ){}

  ngOnInit(){
    this.setBienesInmuebles()
  }

  public async guardarBienInmueble(){
    const res= await this.juridicoBienesController.new({
      juridico_id:this.credito?.juridicos?.id,
      folio_real:this.bienInmueble,
    })

    if(res){
      this.bienesInmuebles.push(res)
      this.bienInmueble=''
      this.showForm=false
    }
  }

  private async setBienesInmuebles(){    
    const id_juridico = this.credito?.juridicos?.id;
    if(id_juridico){
      this.bienesInmuebles= await this.juridicoBienesController.all(id_juridico,{
        juridico_id: this.credito?.juridicos?.id,
        deleted_at:null,
      })
    }    
  }
}
