import { Component, Input, SimpleChanges } from '@angular/core';
import { CollapsableComponent } from '../../../shared/collapsable/collapsable.component';
import { Credito } from '../../../models/credito.model';
import { DatePipe, NgClass } from '@angular/common';
import { ProcesoJudicial } from '../../../models/proceso.judicial';
import { JuridicoEtapaJudicial } from '../../../models/juridico.etapa.judicial';
import { UtilsService } from '../../../services/utils.service';

@Component({
  selector: 'app-resumen-etapas',
  imports: [CollapsableComponent, DatePipe],
  templateUrl: './resumen-etapas.component.html',
  styleUrl: './resumen-etapas.component.css',
})
export class ResumenEtapasComponent {
  @Input() credito!: Credito;

  procesos: ProcesoJudicial[] = [];

  constructor(public utils: UtilsService) {}

  ngOnChanges(changes: SimpleChanges) {
    if (changes['credito']) {
      this.setProcesos();
    }
  }

  private setProcesos() {
    const uniqueProcesses = new Map<number, ProcesoJudicial>();

    this.credito.juridicos?.juridicos_etapas_judiciales?.forEach((jej) => {
      if (jej.etapas_judiciales?.procesos_judiciales) {
        const proceso = jej.etapas_judiciales.procesos_judiciales;
        if (!uniqueProcesses.has(proceso.id)) {
          uniqueProcesses.set(proceso.id, proceso);
        }
      }
    });

    this.procesos = Array.from(uniqueProcesses.values());    
  }

  public etapasDeProceso(proceso: ProcesoJudicial): JuridicoEtapaJudicial[] {
    return (
      this.credito.juridicos?.juridicos_etapas_judiciales?.filter(
        (jej) => jej.etapas_judiciales?.proceso_judicial_id == proceso.id,
      ) ?? []
    );
  }

  goDoc(url: string | undefined) {
    console.log('Opening document:', url);
    if (url) {
      window.open(url, '_blank');
    }
  }
}
