import { inject, Pipe, PipeTransform } from '@angular/core';
import { UtilsService } from '../services/utils.service';
import { Credito } from '../models/credito.model';

@Pipe({
  name: 'fechaetapaprocesal',
  standalone: true
})
export class FechaEtapaProcesalPipe implements PipeTransform {
    private utils = inject(UtilsService)


  transform(credito: Credito | undefined, ...args: unknown[]): unknown {
    const juridico = credito?.juridicos?.juridicos_etapas_judiciales
    const ultimaEtapaActiva = juridico?.sort((a, b) =>
      new Date(b.updated_at ?? '').getTime() - new Date(a.updated_at ?? '').getTime()
    )?.[0];
    if (ultimaEtapaActiva?.fecha) {
      try {
        // Extract the date part (YYYY-MM-DD) and create a proper ISO string
        const datePart = ultimaEtapaActiva.fecha.substring(0, 10) + 'T12:00:00Z';
        const date = new Date(datePart);
        // Check if the date is valid
        if (isNaN(date.getTime())) {
          return null;
        }      
        return this.utils.fechaFormateada(date);

      } catch (e) {
        return null;
      }
    }
    return null;
  }

}
