import { Component, EventEmitter, Input, Output } from '@angular/core';
import { Form, GenericFormComponent, GenericRecord } from '../../../shared/generic-form/generic-form.component';
import { JuridicoService } from '../../../controllers/juridico.service';
import { Juridico} from '../../../models/juridico.model';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';
import { JuridicoJuzgadoEventoService } from '../../../controllers/juridico.juzgado.evento.service';
import { Button } from '../../../shared/button/button.component';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';
import { filter, firstValueFrom } from 'rxjs';
import { CreditoService } from '../../../controllers/credito.service';
import { CreditoDespachoService } from '../../../controllers/credito.despacho.service';

const FORM_DEF: Form = [
  {
    key: 'fecha_asignacion',
    label: 'Fecha de asignación',
    type: 'date',
  },
  {
    key: 'documentos_asignados',
    label: 'Documentos asignados',
    options: ['PAGARE', 'CONTRATO ORIGINAL', 'PAGARE Y CONTRATO ORIGINAL','CONVENIO','NINGUNO'],
    defaultOption:'NINGUNO',
  },
  {
    key: 'estado',
    label: 'Estado:',
    defaultOption:'EXTRAJUDICIAL',
    options: ["EXTRAJUDICIAL" , "JUDICIAL" , "DEPURACIÓN DE SALDOS CONTABLES"],
  },
  {
    key: 'expediente',
    label: 'Expediente',
    type: 'text',
  },
  {
    key: 'juzgado',
    label: 'Juzgado',
    apiUrl:'api/juzgados',
    keyList:'id',
    keyDetalle:'nombre',
  },
  {
    key: 'tipo_juicio',
    label: 'Tipo de juicio',
    options: ['ORAL MERCANTIL', 'EJECUTIVO MERCANTIL'],
  },
];

@Component({
    selector: 'app-form-juridico',
    imports: [
        GenericFormComponent,
    ],
    templateUrl: './form-juridico.component.html',
    styleUrl: './form-juridico.component.css'
})
export class FormJuridicoComponent {
  form= FORM_DEF
  @Input() edit?:Juridico
  @Output() editChange= new EventEmitter<Juridico>()
  @Input() formLocal =false
  credito_id?:number|null
  constructor(
    public juridicoController: JuridicoService,
    private eventoController:JuridicoJuzgadoEventoService,
    private route:ActivatedRoute,
    private utils: UtilsService,
    private dialogService: VanillaDialogService,
    private creditoController: CreditoService,
    private creditoDespachoController: CreditoDespachoService,
  ){}

  deleteButton:Button = {
      text:"Eliminar",
      style:{
        div: "col-auto p-1",
        icon: "bi bi-thrash-fill",
        button: 'btn btn-sm btn-danger scale-05'
      }
  }

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      this.credito_id= this.utils.intOrNull(params.get('credito_id'))
      const juridico_id= this.utils.intOrNull(params.get('juridico_id'))
      if(juridico_id){
        this.edit= await this.juridicoController.find(juridico_id)
      }
    })
  }

  async deleteJuridico(){
    if (!this.edit) return;

    const resp = await firstValueFrom(this.dialogService.show({
      title: 'Confirmar eliminación',
      body: '¿Está seguro de que desea eliminar este registro?',
      respYes: 'Sí, eliminar',
      respNo: 'No, cancelar'
    }).pipe(filter(v => v != null)))

    if (resp.closedByAgree) {
      if (this.credito_id) {
        const credito = await this.creditoController.find(this.credito_id,["*"]);
        if (credito) {
          const despachoActivo = this.utils.despachoActualFromCredito(credito, new Date());        
          if (despachoActivo) {            
            await this.creditoDespachoController.switch(despachoActivo);
          }
          this.creditoController.actualizarEstadoCuenta(credito)
        }        
      }
      await this.juridicoController.switch(this.edit.id)    
      this.edit = undefined;
      this.editChange.emit(this.edit);
    }
  }

  crearEventoJuridico(data:Partial<Juridico&GenericRecord>){
    let actualizacion:string[]=[];
    for(const key of Object.keys(data)){
      actualizacion.push(
        key.toUpperCase() + ' fue actualizado a ' + (data[key]?.toString().toUpperCase()??'nulo')
      )
    }
    this.eventoController.new({
      juridico_id:this.edit!.id,
      fecha: new Date().toISOString().substring(0,10),
      descripcion: "SISTEMA: " + actualizacion.join(', '),
    })
  }
}
