import { Component } from '@angular/core';
import { Button, HeaderButton, TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { UtilsService } from '../../../services/utils.service';
import { Juridico } from '../../../models/juridico.model';
import { JuridicoService } from '../../../controllers/juridico.service';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Conditional } from '../../../controllers/super.service';
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";
import { FormJuridicoComponent } from "../form-juridico/form-juridico.component";
import { FormJuridicoDespachoComponent } from "../form-juridico-despacho/form-juridico-despacho.component";
import { CreditoDespacho } from '../../../models/credito.despacho';

import { CreditoDespachoService } from '../../../controllers/credito.despacho.service';
import { EstadoCuenta } from '../../estado-cuenta/services/utils-estado-cuenta.service';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';

const TABLA_DEF: TableDefinition = {
  columns: [
    {
      key: 'id',
      header: 'ID',
    },
    {
      key: 'row',
      header: 'Estado',
      function: (credito: Credito, utils: UtilsService) => {
        return utils.creditoStatus(credito)
      }
    },
    {
      key: 'row',
      header: 'Cliente',
      function: (row: Credito | undefined, utils: UtilsService) => {
        return utils.nombreClienteFromCredito(row)
      },
      pipe: 'uppercase',
    },
    {
      key: 'row',
      header: 'Municipio',
      function: (row: Credito | undefined, utils: UtilsService) => {
        return utils.municipioFromCredito(row);
      },
      pipe: 'uppercase',
    },
    {
      key: 'estado_cuenta',
      header: 'Pagos Vencidos',
      function: (estado: EstadoCuenta | undefined) => {
        return ((estado?.mensualidades_vencidas ?? 0)).toString()
      },
    },
    {
      key: 'estado_cuenta',
      header: 'Vencido desde',
      subKey: 'vencido_desde',
      pipe: 'date'
    },
    {
      key: 'estado_cuenta',
      header: 'Liquidar Sin Moratorios',
      function: (estado: EstadoCuenta | undefined) => {
        if (!estado) return '0';
        return (estado?.total_a_liquidar ?? 0).toString()
      },
      pipe: 'currency'
    },
    {
      key: 'row',
      header: 'Capital',
      function: (credito: Credito | undefined, utils: UtilsService) => {
        return utils.totalFromCredito(credito).toString()
      },
      pipe: 'currency'
    },
    {
      key: 'fecha_convenio',
      header: 'Fecha Inicio',
      pipe: 'date'
    }
  ]
}

const HEADER_BUTTONS: HeaderButton[] = [
  {
    key: 'asignar_juridico',
    text: 'Asignar A Juridico',
    style: {
      button: 'btn btn-secondary shadow-sm'
    }
  },
  {
    key: 'asignar_juridico_todos',
    text: 'Asignar Todos',
    style: {
      button: 'btn btn-secondary shadow-sm'
    }
  },
]

const EDIT_BUTTON: Button = {
  style: {
    icon: 'bi bi-eye-fill',
    button: 'btn btn-info'
  }
}

@Component({
    selector: 'app-list-creditos',
    imports: [
    TablaComponent,
    BuscadorCreditosComponent,
    FormularioFlotanteComponent,    
    FormJuridicoComponent,
    FormJuridicoDespachoComponent
],
    templateUrl: './list-creditos.component.html',
    styleUrl: './list-creditos.component.css'
})
export class ListCreditosComponent {
  tabla = TABLA_DEF
  extraData: any = {
    filtro: 'juridico-todos'
  }
  title = 'Créditos en Cartera Vencida'
  showForm = false
  currentTab = 1;
  juridicoForm?: Juridico
  creditoDespachoForm?: CreditoDespacho
  headerButtons = HEADER_BUTTONS
  editButton = EDIT_BUTTON
  creditosSelected: Credito[] = []

  conditionals: Conditional[] = []

  relations = [
    'estadoCuenta', 
    'creditosPagos', 
    'convenios.conveniosPagos',
    'abonos',    
    'productosFinancieros', 
    'usuarios', 
    'sucursales', 
    'datosPersonaFisica.datosPersonales', 
    'datosPersonasMorales', 
    'productosFinancieros.plazos',
  
    'datosPersonaFisica.negocios', 
    'creditosDespachos.despachos', 
    'juridicos']
    
  constructor(
    public creditoController: CreditoService,
    private juridicoController: JuridicoService,
    private creditoDespachoController: CreditoDespachoService,
    private dialog: VanillaDialogService    
  ) { 
    
  }

  updateBusquedaAvanzada(extra: any) {    
    this.extraData = {
      filtro: this.extraData.filtro,
      busqueda_avanzada: extra.busqueda_avanzada,
    }    
  }


  applyFilter(filtro: string) {
    if (filtro.includes('extrajudiciales')) {
      this.title = 'Créditos en Extrajudicial'
    } else if (filtro.includes('judiciales')) {
      this.title = 'Créditos en Judicial'
    } else {
      this.title = 'Créditos en Cartera Vencida'
    }

    this.extraData = { filtro }
  }

  manageHeaderButtonEvent(event: string) {    
    switch (event) {
      case 'asignar_juridico':            
        if(this.evaluarCreditoJuricoSeleccionados()) return
        this.abrirFormulario()
    }
  }

  private evaluarCreditoJuricoSeleccionados(){            
    // Ninguno seleccionado
    if (this.creditosSelected.length == 0) {
      this.dialog.show({
        title: 'Advertencia',
        body: 'Selecciona al menos un crédito.',
        tipo: 'warning'
      })
      return true;
    }
    //Ya están en jurídico
    else if (this.creditosSelected.some(c => c.juridicos)) {
      const creditosEnJuridico = this.creditosSelected.filter(c => c.juridicos);
      const creditosIds = creditosEnJuridico.map(c => c.id).join(', ');
      this.dialog.show({
        title: 'Créditos en Proceso Jurídico',
        body: `Los siguientes créditos ya se encuentran en proceso jurídico: ${creditosIds}.`,
        tipo: 'warning'
      });
      return true;
    }          
    //Al menos un crédito se encuentra Finalizado o está saldado
    else if(this.creditosSelected.some(c => c.estado == "FINALIZADO" || c.estado_cuenta?.total_a_liquidar === 0)){            
      const creditosSaldadosFinalizados = this.creditosSelected.filter(c => c.estado == "FINALIZADO" || c.estado_cuenta?.total_a_liquidar === 0).map(c => c.id)
      this.dialog.show({
        title: 'Advertencia',
        body: `Existe al menos 1 crédito saldado en su selección: ${creditosSaldadosFinalizados.join(", ")}. Por favor, revise los créditos seleccionados y elimine aquellos que ya estén saldados.`,
        tipo: 'warning'
      })
      return true;
    }
    return false;
  }

  private abrirFormulario() {
    if (this.creditosSelected.length === 0) return;   
    this.juridicoForm = undefined
    this.creditoDespachoForm = undefined
    this.currentTab = 1
    this.showForm = true
  }

  public async asignarAJuridico() {
    if (!this.juridicoForm) return;
    const juridicosNuevos: Juridico[] = []
    const creditoDespachos: CreditoDespacho[] = []
    this.creditosSelected.filter(credito => !credito.juridicos)
      .forEach((credito) => {
        juridicosNuevos.push({
          ...this.juridicoForm!,
          credito_id: credito.id,
        })
        creditoDespachos.push({
          ...this.creditoDespachoForm!,
          credito_id: credito.id,
        })
      })
    if (juridicosNuevos.length > 0) {
      this.dialog.show({
        title: 'Todo correcto',
        body: juridicosNuevos.length + ' créditos fueron asignados a jurídico de forma correcta.',
        tipo: 'success',
      })
    };
    for (let i = 0; i < juridicosNuevos.length; i++) {
      let res = !!await this.juridicoController.new(juridicosNuevos[i])
      res = res && !!await this.creditoDespachoController.new(creditoDespachos[i])
      if (!res) return;
    }
  }
}
