import { Pipe, PipeTransform } from '@angular/core';
import { Credito } from '../models/credito.model';

@Pipe({
  name: 'fechaUltimaGestion',
  standalone: true
})
export class FechaUltimaGestionPipe implements PipeTransform {

  transform(credito: Credito |undefined, ...args: unknown[]): unknown {
    if(!credito || !credito.credito_evento_cobros?.length) return null;
    const ultimaGestion = credito.credito_evento_cobros
      .sort((a, b) => new Date(b.fecha??'').getTime() - new Date(a.fecha??'').getTime())
      [0];
    return this.formatDate(ultimaGestion.fecha?.substring(0,10)) || null;
  }

  private formatDate(dateString: string | undefined): string | null {
    if (!dateString) return null;
    
    const date = new Date(dateString + 'T17:00:00Z');
    if (isNaN(date.getTime())) return null;
    
    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const year = date.getFullYear().toString().slice(-2);
    
    return `${day}/${month}/${year}`;
  }

}
