import { Component, Input } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { JuridicoEventoCobro } from '../../../models/juridico.event.cobro';
import { JuridicoEventoCobroService } from '../../../controllers/juridico.evento.cobro.service';
import { DatePipe } from '@angular/common';

@Component({
    selector: 'app-bitacora-cobranza',
    imports: [
    DatePipe
],
    templateUrl: './bitacora-cobranza.component.html',
    styleUrl: './bitacora-cobranza.component.css'
})
export class BitacoraCobranzaComponent {
  @Input() credito?:Credito
  
  cobros:JuridicoEventoCobro[]=[]

  constructor(
    private cobroController: JuridicoEventoCobroService,
  ){}

  ngOnInit(){
    this.setCobros()
  }

  private async setCobros(){
    this.cobros= await this.cobroController.all({
      deleted_at:null,
      juridico_id:this.credito?.juridicos?.id
    })
  }
}
