import { Component, Input, SimpleChanges, ViewChild } from '@angular/core';
import { Juridico } from '../../../../models/juridico.model';
import { ProcesoJudicialService } from '../../../../controllers/proceso.judicial.service';
import { JuridicoEtapaJudicialService } from '../../../../controllers/juridico.etapa.judicial.service';
import { ProcesoJudicial } from '../../../../models/proceso.judicial';

import { FormsModule } from '@angular/forms';
import { EtapaJudicial } from '../../../../models/etapa.judicial';
import { JuridicoEtapaJudicial } from '../../../../models/juridico.etapa.judicial';
import { FileInputComponent } from "../../../../shared/file-input/file-input.component";
import { JuridicoJuzgadoEventoService } from '../../../../controllers/juridico.juzgado.evento.service';
import { UtilsService } from '../../../../services/utils.service';
import { Credito } from '../../../../models/credito.model';

@Component({
    selector: 'app-form-etapa-juridico',
    imports: [
    FormsModule,
    FileInputComponent
],
    templateUrl: './form-etapa-juridico.component.html',
    styleUrl: './form-etapa-juridico.component.css'
})
export class FormEtapaJuridicoComponent {
  @Input() credito?:Credito
  @Input() juridico?: Juridico
  @ViewChild('fileInput') fileInput?: FileInputComponent;

  procesos: ProcesoJudicial[] = []
  procesoSelected = 0;

  etapas: EtapaJudicial[] = []
  etapaSelected = 0;  
  fecha = ""
  etapaActualNombre = "";
  fileId = 0;

  /**
   * Las etapas que se ha encontrado el juridico, la ultima la mas reciente
   */
  juridicoEtapas: JuridicoEtapaJudicial[] = []
  juridicoEtapaEdit?: JuridicoEtapaJudicial
  oldEtapa?:JuridicoEtapaJudicial
  private procesosLoaded = false; // New flag

  constructor(
    private procesoController: ProcesoJudicialService,
    private etapaJuridicoController: JuridicoEtapaJudicialService,
    private eventoController: JuridicoJuzgadoEventoService,
    private utils:UtilsService,
  ) { }

  async ngOnInit() { // Make ngOnInit async
    await this.setProcesos(); // Await the process fetching
    this.setJuridicoEtapas();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['juridico'] && this.juridico) {
      this.setJuridicoEtapas()
    }
  }

  onProcesoChange(procesoId: number) {
    this.setEtapasFromProcesoId(procesoId);
    this.etapaSelected = 0;
    this.onEtapaChange();
  }

  onEtapaChange() {
    this.setJuridicoEtapaEdit();
    const etapa = this.buscarEtapaActual();
    this.etapaActualNombre = etapa?.nombre || '';
    this.fecha = this.juridicoEtapaEdit?.fecha?.substring(0, 10) || '';
    this.fileId = this.juridicoEtapaEdit?.id || 0;
  }

  onUrl(newUrl: string) {
    if (this.juridicoEtapaEdit) {
      this.juridicoEtapaEdit.documento_url = newUrl;
      this.etapaJuridicoController.update(this.juridicoEtapaEdit.id, {
        documento_url: newUrl
      });
    }
  }

  async confirmarEtapa() {
    await this.guardarEtapa();
  }

  public async updateFecha(){
    if(this.juridicoEtapaEdit?.fecha?.length==10){
      const res= await this.etapaJuridicoController.update(this.juridicoEtapaEdit.id,{
        fecha:this.juridicoEtapaEdit.fecha
      })
      if(res){
        const proceso= this.buscarProcesoActual()
        const etapa= this.buscarEtapaActual()
        const fecha= new Date().toISOString().substring(0, 10)
        this.eventoController.new({
          juridico_id:this.juridico!.id,
          fecha: fecha,
          descripcion: `${etapa?.nombre.toUpperCase()} - ${proceso?.nombre.toUpperCase()}  EN ${fecha}.`,
        });
      }
    }
  }

  /**
   * Guarda la etapa judicial seleccionada para el jurídico actual.
   * Si la etapa ya existe en el histórico, se actualiza el evento.
   * Si no existe, se crea una nueva etapa y se registra un evento.
   */
  public async guardarEtapa(): Promise<void> {
    if (!this.juridico || !this.etapaSelected) return;

    if(this.juridicoEtapaEdit){
      this.oldEtapa= this.utils.copyOf(this.juridicoEtapaEdit)
    }

    this.setJuridicoEtapaEdit()

    const etapaExistente = this.buscarEtapaExistente();
    if (etapaExistente) {
      etapaExistente.updated_at= new Date().toISOString()
      await this.etapaJuridicoController.update(etapaExistente.id, etapaExistente)
      this.crearNuevoEvento();
      return;
    }

    await this.crearNuevaEtapa();
    this.crearNuevoEvento();
  }

  public setJuridicoEtapaEdit(){
      const etapaExistente = this.buscarEtapaExistente();
      this.juridicoEtapaEdit = etapaExistente;
  }

  /**
   * Busca si la etapa seleccionada ya existe en el histórico de etapas del jurídico.
   * @returns La etapa existente o `undefined` si no se encuentra.
   */
  private buscarEtapaExistente(): JuridicoEtapaJudicial | undefined {
    return this.juridicoEtapas.find(
      (etapa) => etapa.etapa_judicial_id == this.etapaSelected
    );
  }

  /**
   * Crea una nueva etapa judicial para el jurídico actual.
   */
  private async crearNuevaEtapa(): Promise<void> {
    this.juridicoEtapaEdit = await this.etapaJuridicoController.new({
      juridico_id: this.juridico!.id,
      etapa_judicial_id: this.etapaSelected,
      fecha: this.fecha
    });
    if(this.juridicoEtapaEdit){
      this.fileId = this.juridicoEtapaEdit.id;
      this.juridicoEtapaEdit.etapas_judiciales = this.etapas.find((etapa) => etapa.id==this.etapaSelected)
      this.juridicoEtapas.push(this.juridicoEtapaEdit)
      this.credito!.juridicos!.juridicos_etapas_judiciales= this.juridicoEtapas
    }
  }

  /**
   * Crea un nuevo evento en el sistema para registrar el cambio de etapa.
   */
  private async crearNuevoEvento() {
    if (!this.juridicoEtapaEdit) return;

    const proceso = this.buscarProcesoActual();
    const etapa = this.buscarEtapaActual();
    if(!etapa) console.error(this.juridicoEtapaEdit, this.etapas, this.juridicoEtapas)
    const descripcion = this.generarDescripcionEvento(proceso, etapa);
    const res = await this.eventoController.new({
      juridico_id:this.juridico!.id,
      fecha: new Date().toISOString().substring(0, 10),
      descripcion: descripcion,
    });
    if(res) this.credito?.juridicos?.juridicos_juzgados_eventos?.push(res)
  }

  /**
   * Busca el proceso judicial actual basado en el ID seleccionado.
   * @returns El proceso encontrado o `undefined` si no existe.
   */
  private buscarProcesoActual(): ProcesoJudicial | undefined {
    return this.procesos.find((proceso) => proceso.id == this.procesoSelected);
  }

  /**
   * Busca la etapa judicial actual basada en el ID seleccionado.
   * @returns La etapa encontrada o `undefined` si no existe.
   */
  public buscarEtapaActual(): EtapaJudicial | undefined {
    return this.etapas.find((etapa) => etapa.id == this.etapaSelected);
  }

  /**
   * Genera la descripción del evento basada en el proceso y la etapa actual.
   * @param proceso El proceso judicial actual.
   * @param etapa La etapa judicial actual.
   * @returns La descripción formateada del evento.
   */
  private generarDescripcionEvento(
    proceso: ProcesoJudicial | undefined,
    etapa: EtapaJudicial | undefined
  ): string {
    const etapaVieja= this.etapas.find((etapa) => etapa.id == this.oldEtapa?.etapa_judicial_id);
    const procesoViejo = this.procesos.find((proceso) => proceso.id == etapaVieja?.proceso_judicial_id);
    const nombreProceso = proceso?.nombre.toUpperCase() || "Desconocido";
    const nombreEtapa = etapa?.nombre.toUpperCase() || "Desconocido";
    const nombreProcesoViejo = procesoViejo?.nombre.toUpperCase() || "Desconocido";
    const nombreEtapaViejo = etapaVieja?.nombre.toUpperCase() || "Desconocido";
    const fecha = this.juridicoEtapaEdit?.fecha ? ' EN ' +this.juridicoEtapaEdit.fecha.substring(0,10) : ''
    return `${nombreEtapa} - ${nombreProceso}${fecha}`;
  }

  /**
   * Establece las etapas judiciales disponibles basadas en el ID del proceso seleccionado.
   * Si el proceso no tiene etapas asociadas, se inicializa un arreglo vacío.
   *
   * @param procesoId - El ID del proceso judicial seleccionado.
   */
  public setEtapasFromProcesoId(procesoId: number): void {
    const procesoSeleccionado = this.procesos.find(proceso => proceso.id == procesoId);
    this.etapas = procesoSeleccionado?.etapas_judiciales ?? [];
  }

  /**
   * Carga y establece todos los procesos judiciales disponibles desde el servicio.
   * Además, se asegura de que los procesos incluyan sus etapas judiciales asociadas. 
   *
   * Este método es asíncrono y se utiliza durante la inicialización del componente.
   */
  private async setProcesos(): Promise<void> {
    if (this.procesosLoaded) { // Only fetch if not already loaded
      return;
    }
    this.procesos = await this.procesoController.all(
      { deleted_at: null },
      ['etapasJudiciales'],
      {},
      false
    );
    this.procesosLoaded = true; // Set flag after loading
  }

  /**
   * Carga y establece las etapas judiciales asociadas al jurídico actual.
   * Si existen etapas, selecciona la más reciente y actualiza la selección de etapa y proceso.
   */
  private setJuridicoEtapas() {
    if(!this.juridico) return;
    // Obtener todas las etapas judiciales asociadas al jurídico actual
    this.juridicoEtapas = (this.juridico.juridicos_etapas_judiciales??[]).sort((a, b) =>
      new Date(b.updated_at??'').getTime() - new Date(a.updated_at??'').getTime()
    )

    // Si hay etapas asociadas, seleccionar la más reciente
    if (this.juridicoEtapas.length > 0) {
      this.juridicoEtapaEdit = this.juridicoEtapas[0];
      this.fecha = this.juridicoEtapaEdit.fecha?.substring(0,10) || '';

      this.setEtapaSelectedFromId(this.juridicoEtapaEdit.etapa_judicial_id);
    }
  }

  /**
   * Establece la etapa seleccionada basada en el ID de la etapa.
   * También actualiza el proceso seleccionado si la etapa pertenece a un proceso específico.
   *
   * @param etapaId - El ID de la etapa judicial a seleccionar.
   */
  private async setEtapaSelectedFromId(etapaId: number) {
    let etapaFound: EtapaJudicial | undefined;

    if (!this.procesosLoaded) { // Only call setProcesos if not loaded
      await this.setProcesos();
    }

    // Buscar la etapa en todos los procesos disponibles
    for (const proceso of this.procesos) {
      if (etapaFound) continue; // Si ya se encontró la etapa, continuar con el siguiente proceso
      etapaFound = proceso.etapas_judiciales?.find(etapa => etapa.id == etapaId);

      // Si se encuentra la etapa, establecer el proceso seleccionado
      if (etapaFound) {
        this.procesoSelected = proceso.id;
        break; // Salir del bucle una vez que se encuentra la etapa
      }
    }

    // Si no se encuentra la etapa, salir del método
    if (!etapaFound) return;

    // Establecer la etapa seleccionada y actualizar las etapas disponibles para el proceso seleccionado
    this.etapaSelected = etapaFound.id;
    this.setEtapasFromProcesoId(this.procesoSelected);
    this.onEtapaChange();
  }
}
